/**
 * @param {number[]} nums
 * @return {number}
 */
var minMoves = function(nums) {
    const min = Math.min(...nums);
    let sum = 0;

    for (const num of nums) {
        sum += num - min;
    }

    return sum;
};

/**
 * @param {number[]} nums
 * @return {number}
 */
var minMoves = function(nums) {
    nums.sort((a, b) => a - b);

    let acc = 0;

    for (let i = 1; i < nums.length; i++) {
        acc += (nums[i] + acc) - nums[i - 1];
    }

    return acc;
};

/**
 * @param {number[]} nums
 * @return {number}
 */
var minMoves = function(nums) {
    nums.sort((a, b) => a - b);

    const n = nums.length;
    const dp = Array(n + 1).fill(0);
    let sum = 0;

    for (let i = 1; i < n; i++) {
        const diff = (nums[i] + dp[i]) - nums[i - 1];
        dp[i + 1] = diff;
        sum += diff;
    }

    return sum;
};
